import{z as o,x as d,o as E,c as A,q as r,j as i,D as e,d as t,s as l,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"k-匿名","description":"","frontmatter":{"title":"k-匿名","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/k-anonymity.md","filePath":"cs/k-anonymity.md","lastUpdated":1791063341000}'),p={name:"cs/k-anonymity.md"};function D(k,a,m,C,h,c){const B=d("Mermaid");return E(),A("div",null,[a[2]||(a[2]=r('<h1 id="k-匿名" tabindex="-1">k-匿名 <a class="header-anchor" href="#k-匿名" aria-label="Permalink to &quot;k-匿名&quot;">​</a></h1><div class="epigraph"><p>k-匿名要求每条准标识组合至少对应 k 人。它挡直接指名，挡不住同质敏感值与背景知识。后续有 l-多样与 t-接近，但句法方法仍弱于 DP 的最坏保证。</p><footer>—— Sweeney, k-anonymity, International Journal on Uncertainty, Fuzziness and Knowledge-based Systems, 2002</footer></div><p>上一课<a href="/cs/differential-privacy">差分隐私</a>给了最坏情形可加预算的保证；缺口是工程与合规里仍到处出现的 <strong>k-匿名表</strong>。本课讲它挡什么、不挡什么，与 DP 的差距在哪。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>去掉姓名字段不等于匿名：邮编、生日、性别的组合在人口里常常唯一，Sweeney 据此演示过再识别。k-匿名的回答是泛化准标识——邮编截成前三位、生日并成年度——直到每个准标识组合至少对应 k 人。缺口是同质性攻击：一组 k 人若敏感值全相同（k 人患同一病），「这组里有病」就等于「这组每人都有病」，组内是完全泄漏。</p><p><span class="marginnote">术语翻译：准标识（quasi-identifier）就是「不在名单上、却能锁定你」的字段组合——邮编、生日、性别这些看似无害的列。单列不唯一，组合起来常常唯一。</span></p><p><span class="marginnote">数字实例：Sweeney 统计过，约 87% 的美国人能被「邮编 + 生日 + 性别」三元组唯一锁定——三亿人里大半带着天然指纹。这就是为什么删掉姓名一列远远不叫匿名化。</span></p><h3 id="组合发布" tabindex="-1">组合发布 <a class="header-anchor" href="#组合发布" aria-label="Permalink to &quot;组合发布&quot;">​</a></h3><p>多次发布更糟：同一人群的两张 k-匿名表放在一起，准标识可交叉还原——k-匿名没有 DP 那样的组合定理，发布两次，保证就漏两次。</p><p><span class="marginnote">Sweeney 2002。GDPR 下一课把法律要求接到技术。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把 k-匿名与 DP 并排对照：k-匿名是句法性质——只看表结构就能检查，不对攻击者的背景知识做假设；DP 是语义性质——对相邻数据集给概率保证。动机按类别点名：医疗与行政公开数据一再发生再识别事故，由此推动 l-多样（组内敏感值至少 l 种）与 t-接近（组内敏感值分布贴近整体）的修补。下一课 GDPR 技术含义。</p>',13)),(E(),i(s,null,{default:e(()=>[l(B,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20QID%5B%22%E5%87%86%E6%A0%87%E8%AF%86%22%5D%20--%3E%20GEN%5B%22%E6%B3%9B%E5%8C%96%E5%88%B0%20k%20%E4%BA%BA%E4%B8%80%E7%BB%84%22%5D%0A%20%20GEN%20--%3E%20HOMO%5B%22%E5%90%8C%E8%B4%A8%E6%95%8F%E6%84%9F%E5%80%BC%E4%BB%8D%E6%BC%8F%22%5D%0A%20%20DP%5B%22%E5%B7%AE%E5%88%86%E9%9A%90%E7%A7%81%22%5D%20--%3E%20WORST%5B%22%E6%9C%80%E5%9D%8F%E7%9B%B8%E9%82%BB%E4%BF%9D%E8%AF%81%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"机制上，句法匿名是启发式：它挡「直接指名」，对攻击者知道什么不做任何建模——攻击者一旦知道目标在某组里，组的保证立刻缩水到那一组。l-多样与 t-接近各自封一条同质或分布攻击，但封不完：攻击者的知识集合无法枚举，这正是 DP 用「相邻数据集」重新定义问题的原因。法律下一课不会只接受 k。",-1)),(E(),i(s,null,{default:e(()=>[l(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%AE%B0%E5%BD%95%EF%BC%9A%E9%82%AE%E7%BC%96%20100084%EF%BC%8C%E7%94%9F%E6%97%A5%201990-05-12%22%5D%20--%3E%7C%22%E5%8E%9F%E6%A0%B7%E5%8F%91%E5%B8%83%22%7C%20B%5B%22%E5%85%A8%E5%9F%8E%E5%94%AF%E4%B8%80%EF%BC%8C%E7%9B%B4%E6%8E%A5%E5%86%8D%E8%AF%86%E5%88%AB%22%5D%0A%20%20A%20--%3E%7C%22%E7%94%9F%E6%97%A5%E5%B9%B6%E6%88%90%E5%B9%B4%E4%BB%BD%22%7C%20C%5B%22%E5%90%8C%E7%BB%84%202%20%E4%BA%BA%EF%BC%8C%E4%B8%8D%E8%B6%B3%20k%3D3%22%5D%0A%20%20C%20--%3E%7C%22%E9%82%AE%E7%BC%96%E6%88%AA%E6%88%90%E5%89%8D%E5%9B%9B%E4%BD%8D%22%7C%20D%5B%22%E5%90%8C%E7%BB%84%207%20%E4%BA%BA%EF%BC%8C%E8%BE%BE%E5%88%B0%20k%3D3%22%5D%0A%20%20D%20--%3E%20OK%5B%22%E9%80%9A%E8%BF%87%E5%8F%A5%E6%B3%95%E6%A3%80%E6%9F%A5%22%5D%0A%20%20OK%20--%3E%20BUT%5B%22%E7%BB%84%E5%86%85%E6%95%8F%E6%84%9F%E5%80%BC%E8%8B%A5%E5%85%A8%E7%9B%B8%E5%90%8C%EF%BC%8C%E4%BB%8D%E7%84%B6%E5%85%A8%E7%BB%84%E6%B3%84%E6%BC%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写再识别教程；边界要点名：k 的取值没有原理性答案，从 k=5 提到 k=50 只是抬高再识别成本一段，而泛化每加深一层，数据的分析价值就跌一层。GDPR 技术含义下一课。</p><p><span class="marginnote">常见误区：初学者容易以为「把 k 设得越大越安全」。实际上泛化每糊一层，年龄、地域的精度就丢一层，统计价值跟着掉——k 是隐私与效用之间的旋钮，不是越高越好的安全等级。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DP 有预算；k-匿名是句法。</li><li>挡指名，不挡同质与背景知识。</li><li>多表发布会交叉。</li><li>下一课 GDPR。</li><li>出处：Sweeney, 2002；对照 Dwork and Roth。</li></ul>',5))])}const F=o(p,[["render",D]]);export{f as __pageData,F as default};
